// Tag which channel this order came in through
return items.map(item => {
  item.json.__source = 'client_form';
  return item;
});

// Normalize form fields into a clean, predictable structure.
// Handles both custom JSON webhooks and nested Typeform payloads.
let f = items[0].json.body || items[0].json;

// Check if this is a Typeform webhook payload
if (f && f.form_response) {
  const answers = f.form_response.answers || [];
  const fields = f.form_response.definition.fields || [];
  const fieldMap = {};
  for (const field of fields) {
    fieldMap[field.id] = { ref: field.ref, title: field.title };
  }
  const parsed = {};
  for (const ans of answers) {
    const def = fieldMap[ans.field.id] || {};
    const key = def.ref || def.title;
    let val = null;
    if (ans.type === 'text') val = ans.text;
    else if (ans.type === 'number') val = ans.number;
    else if (ans.type === 'choice') val = ans.choice.label;
    else if (ans.type === 'date') val = ans.date;
    else if (ans.type === 'email') val = ans.email;
    else if (ans.type === 'phone_number') val = ans.phone_number;
    else if (ans.type === 'boolean') val = ans.boolean;
    if (key) parsed[key] = val;
  }
  f = parsed;
}

const fullName = f['Full Name'] || f['name'] || '';
const phone = f['Phone Number'] || f['phone'] || '';
const whatsapp = f['WhatsApp Number (if different)'] || f['whatsapp_number'] || phone;
const email = f['Email Address (for invoice delivery)'] || f['email'] || null;
const eventDate = f['Event Date'] || f['event_date'] || '';
const venue = f['Venue Address'] || f['venue_address'] || '';
const guests = Number(f['Number of Guests'] || f['guest_count'] || 0);
const sound = f['Sound System'] || f['sound_system'] || 'None';
const notes = f['Special Notes'] || f['notes'] || '';
const source = f.__source || items[0].json.__source || 'client_form';

return [{
  json: {
    name: fullName,
    phone: phone,
    whatsapp_number: whatsapp,
    email: email,
    event_date: eventDate,
    venue_address: venue,
    guest_count: guests,
    notes: notes,
    source: source,
    sound_system: sound
  }
}];

const year = new Date().getFullYear();
const seq = String($input.first().json.seq).padStart(4, '0');
const order_ref = `ZC-${year}-${seq}`;

const original = $('Normalize Order Data').first().json;
const clientId = $('Upsert Client').first().json.id;

return [{
  json: { ...original, order_ref, client_id: clientId }
}];

