}

const orderRef = (f['Order Ref (e.g. ZC-2026-0001)'] || f['Order Reference'] || f['order_ref'] || '').trim();
const clientEmail = (f['Client Email Address'] || f['client_email'] || f['email'] || '').trim();
const menuPrice = Number(f['Menu Price per Person (PKR)'] || f['menu_price'] || 0);
const soundPrice = Number(f['Sound System Price (PKR)'] || f['sound_price'] || 0);
const otherCharges = Number(f['Setup/Tent/Other Charges (PKR)'] || f['other_charges'] || 0);

const agreedTotal = Number(f['Agreed Total Price (PKR)'] || f['agreed_total_price'] || (menuPrice * Number(f['Number of Guests'] || 1) + soundPrice + otherCharges));
const advancePaid = Number(f['Advance Paid Now (PKR, 0 if none)'] || f['Advance Amount (PKR)'] || f['advance_paid'] || 0);
const advanceMethod = (f['Advance Payment Method'] || f['Payment Method'] || f['advance_method'] || 'None').toLowerCase();

return [{ json: {
  order_ref: orderRef,
  client_email: clientEmail || null,
  agreed_total_price: agreedTotal,
  advance_paid: advancePaid,
  advance_method: advanceMethod
}}];

const year = new Date().getFullYear();
const seq = String($input.first().json.seq).padStart(4, '0');
const invoice_number = `ZC-INV-${year}-${seq}`;
const { agreed_total_price, advance_paid } = $('Normalize Input').first().json;
const orderId = $('Find Order By Ref').first().json.id;
let status = 'unpaid';
if (advance_paid >= agreed_total_price) status = 'paid';
else if (advance_paid > 0) status = 'partial';
return [{ json: { invoice_number, order_id: orderId, total: agreed_total_price, paid_amount: advance_paid, status } }];

const invoice = $('Get Invoice + Order + Client').first().json;

// Format dates
const issuedDate = invoice.issued_at ? new Date(invoice.issued_at).toLocaleDateString('en-GB') : '';
const eventDate = invoice.event_date ? new Date(invoice.event_date).toLocaleDateString('en-GB') : '';

// Call admin portal's built-in PDF generator
const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://zain-admin-portal.onrender.com/api/generate-invoice-pdf',
  headers: { 'Content-Type': 'application/json' },
  body: {
    invoice_number: invoice.invoice_number || '',
    order_ref: invoice.order_ref || '',
    issued_date: issuedDate,
    event_date: eventDate,
    client_name: invoice.client_name || '',
    client_phone: invoice.client_phone || '',
    venue_address: invoice.venue_address || 'Not specified',
    guest_count: invoice.guest_count || '',
    invoice_status: invoice.status || '',
    total: invoice.total || 0,
    paid_amount: invoice.paid_amount || 0,
    balance: invoice.balance || 0
  },
  encoding: 'arraybuffer',
  returnFullResponse: false
});

const buffer = Buffer.from(response);
return [{
  json: {
    invoice_id: invoice.invoice_id,
    invoice_number: invoice.invoice_number,
    client_name: invoice.client_name
  },
  binary: {
    data: await this.helpers.prepareBinaryData(buffer, (invoice.invoice_number || 'invoice') + '.pdf', 'application/pdf')
  }
}];

